                    "sql": "create or replace table Maplemonk.Healthy_Master_PNL_Fact_Items as select awb, coalesce(sc.marketplace, mc.marketplace) marketplace, coalesce(sc.channel_mapped, mc.marketing_channel) as channel, sc.order_id, reference_code, sku, sku_code, commonsku, product_id, coalesce(sc.order_date,mc.date) order_date, order_time, mrp_sales, QUANTITY, mrp_sales * Quantity as MRP, sm.cogs, sm.cogs * sc.quantity as SALE_COGS, CASE WHEN IFNULL(returned_sales,0) > 0 THEN sm.cogs * sc.quantity ELSE 0 END AS return_cogs, CASE WHEN IFNULL(cancelled_quantity,0) > 0 THEN sm.cogs * sc.cancelled_quantity ELSE 0 END AS cancelled_cogs, GROSS_SALES_BEFORE_TAX, DISCOUNT, tax, CASE WHEN IFNULL(returned_sales,0) > 0 THEN tax ELSE 0 END AS return_tax, SHIPPING_PRICE, SELLING_PRICE, CASE WHEN IFNULL(cancelled_quantity,0) >0 THEN SELLING_PRICE ELSE 0 END AS Cancelled_sales, coalesce(sm.product_title, sc.PRODUCT_NAME_FINAL) PRODUCT_NAME_FINAL, PRODUCT_CATEGORY, coalesce(sm.PRODUCT_TYPE, sc.product_type) PRODUCT_TYPE, FINAL_SHIPPING_STATUS, city, state, PAYMENT_GATEWAY, Payment_Mode, COURIER, returned_quantity, returned_sales, cancelled_quantity, shipment_cost, safe_divide(coalesce(spend,0), count(1) over (partition by coalesce(sc.order_date,mc.date), coalesce(sc.channel_mapped, mc.marketing_channel), coalesce(sc.marketplace,mc.marketplace))) spend, coalesce(ad_impressions,0) ad_impressions, coalesce(ad_clicks,0) ad_clicks, coalesce(ad_conversions,0) ad_conversions, safe_divide(coalesce(ad_sales,0),count(1) over (partition by coalesce(sc.order_date,mc.date), coalesce(sc.channel_mapped, mc.marketing_channel), coalesce(sc.marketplace,mc.marketplace))) ad_sales from (select *, case when lower(channel) like any (\'%facebook%\',\'%fb%\',\'%meta%\',\'%insta%\',\'%ig%\') then \'FACEBOOK\' when lower(channel) like any (\'%google%\') then \'GOOGLE\' else upper(channel) end channel_mapped from maplemonk.healthymaster_wh_471810_sales_consolidated WHERE UPPER(marketplace) LIKE (\'%WEBSITE%\') ) sc full outer join ( select date ,case when lower(channel) like any (\'%facebook%\', \'%google%\') then \'WEBSITE D2C\' else upper(channel) end as Marketplace ,upper(channel) marketing_Channel ,sum(ifnull(spend,0)) as spend ,sum(ifnull(impressions,0)) as ad_impressions ,sum(ifnull(clicks,0)) as ad_clicks ,sum(ifnull(conversions,0)) as ad_conversions ,sum(ifnull(conversion_value,0)) as ad_sales from healthymaster-wh-471810.maplemonk.healthymaster_wh_471810_MARKETING_CONSOLIDATED where channel in (\'GOOGLE\',\'FACEBOOK\') group by 1,2,3 ) mc on date(sc.order_Date) = date(MC.date) and lower(SC.channel_mapped)=lower(MC.marketing_channel) and upper(sc.marketplace) = upper(mc.marketplace) left join( select platform, Shopify_SKU, CAST(NULLIF(REPLACE(COGS, \',\', \'\'), \'#N/A\')AS float64) cogs, product_type, PRODUCT_TITLE from `maplemonk.gs_Updated_SKU_MASTER` where lower(platform) = \'shopify\' qualify row_number() over (partition by shopify_sku order by cast(cogs as float64) desc)=1) sm on UPPER(sc.SKU) = UPPER(sm.shopify_sku) LEFT JOIN( select distinct trackId, order_id, shipment_cost from `maplemonk.HM_vamaship_surface_tracking`) shc on sc.awb = shc.trackId ;",
